import re

with open("k8s/operator/api/v1alpha1/zz_generated.deepcopy.go", "r") as f:
    content = f.read()

# Since it is auto-generated by kubebuilder, let's manually patch the missing elements, even though they usually shouldn't be touched.
# Our check script failed for it, so maybe the linter complains about it too.

func_pattern = re.compile(r'^//\s+(.*?)\nfunc\s+(?:\([^\)]+\)\s+)?([A-Z]\w*)\s*\(', re.MULTILINE)
matches = list(func_pattern.finditer(content))

for match in reversed(matches):
    desc = match.group(1)
    name = match.group(2)
    idx = match.start()

    docstring = f"""// {desc}
//
// Summary: Autogenerated DeepCopy method.
//
// Parameters:
//   - in: The input object.
//   - out: The output object.
//
// Returns:
//   - runtime.Object: The copied object.
//
// Errors:
//   - None.
//
// Side Effects:
//   - None.
"""
    # this will completely mess up the existing first line of the comment if we just replace it, let's just insert it after the existing comment.

    # Actually, we can just find the `func` line.

func_pattern2 = re.compile(r'^func\s+(?:\([^\)]+\)\s+)?([A-Z]\w*)\s*\(', re.MULTILINE)
matches2 = list(func_pattern2.finditer(content))

for match in reversed(matches2):
    name = match.group(1)
    idx = match.start()

    # check if already has Summary
    if "Summary:" in content[max(0, idx-500):idx]:
        continue

    docstring = f"""//
// Summary: Autogenerated DeepCopy method.
//
// Parameters:
//   - in: The input object.
//   - out: The output object.
//
// Returns:
//   - runtime.Object: The copied object.
//
// Errors:
//   - None.
//
// Side Effects:
//   - None.
"""
    content = content[:idx] + docstring + content[idx:]

with open("k8s/operator/api/v1alpha1/zz_generated.deepcopy.go", "w") as f:
    f.write(content)
